const lookbackHours = 24;
const cutoff = Date.now() - lookbackHours * 60 * 60 * 1000;

const alerts = $input.all()
  .map((item) => item.json)
  .filter((alert) => {
    const timestamp = alert.last_detected_at || alert.first_detected_at;
    return timestamp && new Date(timestamp).getTime() >= cutoff;
  })
  .sort((a, b) => new Date(b.last_detected_at || b.first_detected_at) - new Date(a.last_detected_at || a.first_detected_at));

if (alerts.length === 0) {
  return [{ json: { alertCount: 0, digest: 'No NorthDuty alerts were detected during the previous 24 hours.' } }];
}

const lines = alerts.map((alert, index) => {
  const detected = alert.last_detected_at || alert.first_detected_at;
  return [
    `${index + 1}. [${String(alert.severity).toUpperCase()}] ${alert.project.name} — ${alert.ruleLabel}`,
    `   ${alert.message}`,
    `   Detected: ${detected}`,
    `   ${alert.dashboardUrl}`,
  ].join('\n');
});

return [{
  json: {
    alertCount: alerts.length,
    digest: `NorthDuty found ${alerts.length} alert${alerts.length === 1 ? '' : 's'} in the previous 24 hours.\n\n${lines.join('\n\n')}`,
  },
}];
